steps.codeExample:
struct Heroi {
    hp: i32,
}

impl Heroi {
    fn esta_vivo(&self) -> bool {
        self.hp > 0
    }
}

fn main() {
    let h = Heroi { hp: 80 };
    println!("Vivo? {}", h.esta_vivo());
}

